// Supabase Edge Function for the public REST API.
// handler.js is generated by `npm run build:api` from src/lib/api.
//
// Deploy it without JWT verification (the API has its own keys):
//   supabase functions deploy api --no-verify-jwt
// It needs no secrets: SUPABASE_URL and SUPABASE_ANON_KEY are provided by the platform.
// The service_role key is not used.
import { createApiHandler } from "./handler.js";

declare const Deno: { env: { toObject(): Record<string, string> }; serve(handler: (request: Request) => Promise<Response>): void };

Deno.serve(createApiHandler(() => Deno.env.toObject()));
